!function(a){function n(n){for(var m,r,p=n[0],o=n[1],c=n[2],g=0,s=[];g<p.length;g++)r=p[g],Object.prototype.hasOwnProperty.call(t,r)&&t[r]&&s.push(t[r][0]),t[r]=0;for(m in o)Object.prototype.hasOwnProperty.call(o,m)&&(a[m]=o[m]);for(d&&d(n);s.length;)s.shift()();return i.push.apply(i,c||[]),e()}function e(){for(var a,n=0;n<i.length;n++){for(var e,r=i[n],p=!0,o=1;o<r.length;o++)e=r[o],0!==t[e]&&(p=!1);p&&(i.splice(n--,1),a=m(m.s=r[0]))}return a}function m(n){if(r[n])return r[n].exports;var e=r[n]={i:n,l:!1,exports:{}};return a[n].call(e.exports,e,e.exports,m),e.l=!0,e.exports}var r={},t={36:0},i=[];m.m=a,m.c=r,m.d=function(a,n,e){m.o(a,n)||Object.defineProperty(a,n,{enumerable:!0,get:e})},m.r=function(a){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(a,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(a,"__esModule",{value:!0})},m.t=function(a,n){if(1&n&&(a=m(a)),8&n)return a;if(4&n&&"object"==typeof a&&a&&a.__esModule)return a;var e=Object.create(null);if(m.r(e),Object.defineProperty(e,"default",{enumerable:!0,value:a}),2&n&&"string"!=typeof a)for(var r in a)m.d(e,r,function(n){return a[n]}.bind(null,r));return e},m.n=function(a){var n=a&&a.__esModule?function(){return a.default}:function(){return a};return m.d(n,"a",n),n},m.o=function(a,n){return Object.prototype.hasOwnProperty.call(a,n)},m.p="";var p=window.webpackJsonp=window.webpackJsonp||[],o=p.push.bind(p);p.push=n,p=p.slice();for(var c=0;c<p.length;c++)n(p[c]);var d=o;i.push([182,0]),e()}({182:function(a,n,e){"use strict";e.r(n);var m=e(0);Object(m.a)("de","army",e(183),e(1))},183:function(a){a.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"火炮","link":"de_army#de_army_cannon"}],"model":"75mm反坦克炮","description":"<p>75mm反坦克炮是二战德军反坦克作战的主力火炮装备，该火炮先后研制有Pak40、Pak41、Pak42、Pak50和Pak97/38等多种型号，其中以75mm Pak40型产量最多（共生产了23000门）。</p><p>75mm反坦克炮有着比37mm、50mm反坦克炮更大的威力，在一定距离内，发射穿甲弹能击穿对手的中、重型坦克装甲和坚固工事，也能使用高爆弹大面积杀伤对方士兵。二战中，德军战斗激烈且频繁，75mm反坦克炮的战损十分严重，尽管1942年2月后德国工厂全速运转，将产量从1942年7月的 170多台/月提高到1944年的975台/月，但仍难以满足前线部队需求，只能在一些重要战线的关键部队中进行装备。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_cannon75at_11.jpg","description":"<h6>75mm Pak40型反坦克炮</h6><p>75mm Pak40是在Pak38基础上研制的，1941年正式装备德军，目的是对付苏军的T-34与KV坦克；它使用穿甲弹（PzGr.39）可在1000米距离上击穿30度倾角89mm均质钢装甲，而使用钨心穿甲弹可在1000米距离上击穿30度倾角96mm均质钢装甲。另外，它也可以发射高爆弹支援步兵，也可以发射烟雾弹作掩护，是德军在战场上一把利器。</p><p>技术数据：</p><p>火炮口径：75mm；</p><p>炮管长：3.450米，带膛线炮管长: 2.461米；</p><p>火炮全重：战斗1.425吨，运输1.5吨；</p><p>最高牵引速度：40千米/小时；</p><p>火炮射界（水平方向）：58度，火炮射角（垂直方向）：-5～22度；</p><p>射速：12～15发/分钟；</p><p>最远射程：10000米，最远瞄准距离：2000米，有效射程：900米。</p><p>炮班人数：8人。</p>","caption":""},{"image":"imgs/de/army/de_army_cannon75at_12.jpg","description":"<h6>75mm Pak40型反坦克炮炮弹</h6><p></p><p>图例：</p><p>1.钨心穿甲弹PzGr 40（APCR）<br>2.钨心穿甲弹PzGr 40M（APCR）<br>3.破甲弹38 HL/A（HEAT）<br>4.破甲弹38 HL/B（HEAT）</p>","caption":""},{"image":"imgs/de/army/de_army_cannon75at_21.jpg","description":"<h6>75mm Pak41型反坦克炮</h6><p>75mm Pak41与75mm Pak40是同期研发的反坦克炮，但与75mm Pak40不同的是：75mm Pak41的炮管是一种圆柱锥膛结构，它的炮身尾部至炮口处逐渐缩窄，将膛压增大，从而提高弹丸初速；75mm Pak41锥膛炮大大增加了射出炮弹的威力，其穿甲能力可在1500米内击穿60mm厚装甲；但由于该炮要使用钨芯穿甲弹，而德国因钨矿缺乏，另外也因为炮弹制作难度大，所以在少量生产后只能放弃。</p>","caption":""},{"image":"imgs/de/army/de_army_cannon75at_31.jpg","description":"<h6>75mm Pak50型反坦克炮</h6><p>75mm Pak50反坦克炮是在二战后期1944年研制生产的，目的是想将75mm炮改变为反坦克炮与步兵炮相结合的综合型火炮，该炮将Pak40的3.45米炮管改短为2.3米，加装了炮口制退器，但改装后发现其威力弱于Pak40炮，另外战争也到了后期，生产工厂已受轰炸，因此也仅作了少量生产。</p>","caption":""},{"image":"imgs/de/army/de_army_cannon75at_42.jpg","description":"<h6>75mm Pak97/38型反坦克炮</h6><p>二战初期，德军在波兰与西线战场上缴获了数千门75mm火炮（1897型加农炮），以及大量炮弹（超过5000万枚），1942年，德军将这些火炮炮管加长并加装了炮口制退器，将其安装在Pak38的炮架上，于是就成为了75mm Pak97/38型反坦克炮。</p><p>该炮从1942年初开始生产到1943年7月停产，一年半时间共改装生产了3700多门，全部装备给德军二等步兵师的反坦克部队，该炮的弹道数据与75mm Pak40型基本相同，在东线与西线战场上都有作战记录。</p>","caption":""}],"part2title":"战场上的75mm反坦克炮","part2description":"","part2content":[{"image":"imgs/de/army/de_army_cannon75at_13.jpg","description":"东线苏联战场，正在作战中的德军一门75mm Pak40型反坦克炮。这门反坦克炮完全按照作战规范安放在靠近林线的土制护墙后面，炮管与炮身还采取了很多隐蔽措施，支腿、枪管和防盾都也都用树叶进行了伪装。四名炮班成员分工合作，其中一名装填手熟练地将炮弹推上膛，另一名弹药手同时从金属筒中倒出一发炮弹，准备将其传递，从中可看出德军炮手平时训练有素。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_14.jpg","description":"东线苏联战场，德军的75mm Pak40型反坦克炮阵地上，一位士兵操着MG42通用机枪警惕地注视着前方，机枪旁边还有备用枪管和弹药，以防止敌方步兵对火炮阵地的袭击。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_15.jpg","description":"1941年冬天，东线苏联战场，一门德军的75mm Pak40型反坦克炮安装在公路边，保护公路上行驶的德军车队免受苏军坦克的突袭。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_16.jpg","description":"德军一门75mm Pak40型反坦克炮正在炮组成员努力下进入射击阵地。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_17.jpg","description":"1943年初，东线苏联战场，在别尔哥罗德（Bielgorod）东北地区作战，隶属“大德意志”装甲掷弹兵师的一门75mm Pak40型反坦克炮正准备射击。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_18.jpg","description":"1943年10月，东线苏联战场基辅地区，德军败退时遗弃的一门75mm Pak40型反坦克炮。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_19.jpg","description":"1943年秋天，东线苏联战场斯摩棱斯克西部地区，一群苏军士兵正在检查一门被缴获的德军75mm Pak40型反坦克炮。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_21.jpg","description":"1944年春季，东线战场白俄罗斯巴拉诺维奇（Baranavichi）地区，隶属德军第36步兵师第36装甲营的一门75mm Pak41型反坦克炮。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_22.jpg","description":"1942年夏天，东线苏联战场，隶属德军第30步兵师第30装甲营的一门75mm Pak41型反坦克炮正在全履带地形车的牵引下向前线开进。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_32.jpg","description":"1944年秋天，西线法国战场，德军一门伪装得很好的75mm Pak50型反坦克炮。图中仍可依稀见到其炮口制退器，炮班士兵正隐蔽在火炮前的炮坑中认真观察敌情。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_41.jpg","description":"1942年，东线苏联战场加里宁地区，一门在战斗中被苏军击毁的德军75mm Pak97/38型反坦克炮。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_42.jpg","description":"1944年，西线法国战场，德军一门作了伪装的75mm Pak97/38型反坦克炮正准备发射，弹药手已将下一发炮弹拿在手上，待火炮发射后马上传递给装填手。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_43.jpg","description":"东线战场上在火炮阵地中作好了战斗准备的德军一门75mm Pak97/38型反坦克炮，尽管该炮重量较轻（重1.19吨）便于转移，但因其射速较低（10～12发/分钟），故在德军反坦克部队中评价并不高。","caption":""},{"image":"imgs/de/army/de_army_cannon75at_44.jpg","description":"1942年8月，西线战场，英军与加拿大军对法国北部沿岸港口城市迪耶普实施的一次试探性登陆中，受到德军反击，图中是参与迪耶普战斗的德军一门75mm Pak97/38型反坦克炮。","caption":""}]}')}});